import { Hono } from 'hono';
import { z } from 'zod';
import type { AdapterBundle } from '../../contracts.js';

const ShareRequestSchema = z.object({ userId: z.string(), fileId: z.string() });

export function registerShareRoutes(app: Hono, adapters: AdapterBundle): void {
  app.post('/v1/files/share', async (c) => {
    const { userId, fileId } = ShareRequestSchema.parse(await c.req.json());
    const link = await adapters.store.createShareLink(userId, fileId);
    return c.json({ link });
  });
}
